package com.scamshield.incident; import com.scamshield.common.repo.*; import com.scamshield.common.domain.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/incidents") public class IncidentController { private final IncidentRepository incidents; private final EscalationRepository escalations; private final ReportRepository reports; private static final Set<String> STATUSES=Set.of("OPEN","UNDER_INVESTIGATION","ESCALATED","RESOLVED","FALSE_POSITIVE"); public IncidentController(IncidentRepository i,EscalationRepository e,ReportRepository r){incidents=i;escalations=e;reports=r;} private void auth(String key){if(key==null||!key.equals(System.getenv().getOrDefault("SCAMSHIELD_ADMIN_KEY","demo-admin-key")))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"Admin authentication required");} @GetMapping public List<Incident> all(@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);return incidents.findAllByOrderByUpdatedAtDesc();} @GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id,@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);Incident i=incidents.findById(id).orElseThrow();return Map.of("incident",i,"reports",reports.findByPhoneNumberOrderByCreatedAtDesc(i.phoneNumber),"escalations",escalations.findByIncidentIdOrderByCreatedAtDesc(id));} @PatchMapping("/{id}") public Incident status(@PathVariable Long id,@RequestBody Map<String,String> body,@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);String s=body.get("status");if(!STATUSES.contains(s))throw new IllegalArgumentException("Invalid incident status");Incident i=incidents.findById(id).orElseThrow();i.status=s;i.updatedAt=LocalDateTime.now();return incidents.save(i);} @PostMapping("/{id}/escalate") public Map<String,Object> escalate(@PathVariable Long id,@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);Incident i=incidents.findById(id).orElseThrow();String ref="EXT-"+i.reference+"-"+(escalations.count()+1); Escalation e=new Escalation();e.incidentId=id;e.destination="Mock Provider Security Operations";e.externalReference=ref;e.status="QUEUED";e.createdAt=LocalDateTime.now();escalations.save(e);i.status="ESCALATED";i.escalationReference=ref;i.updatedAt=LocalDateTime.now();incidents.save(i);return Map.of("simulated",true,"status","QUEUED","destination",e.destination,"reference",ref,"createdAt",e.createdAt);} }
